import type { Result } from "@/shared/result";

/** A dataset file as read, not yet validated. */
export type DatasetFile = { file: string; content: unknown };

export type DatasetSourceError =
  /** `command` is the one that generates the file. */
  | { kind: "missing-file"; file: string; command: string }
  | { kind: "invalid-json"; file: string; reason: string };

/** The local JSON files of the dataset (ING-cli-local), generated by `pnpm ingest menu` and `pnpm ingest recipes`. */
export interface DatasetSource {
  readMenus(): Promise<Result<DatasetFile, DatasetSourceError>>;
  readRecipes(): Promise<Result<DatasetFile, DatasetSourceError>>;
}
